import { useQueryClient } from '@tanstack/react-query';

function UserLink({ userId }: { userId: number }) {
  const queryClient = useQueryClient();

  const prefetchUser = async () => {
    await queryClient.prefetchQuery({
      queryKey: ['user', userId],
      queryFn: () => fetchUser(userId),
      staleTime: 1000 * 60 * 5
    });
  };

  return (
    <div onMouseEnter={prefetchUser}>
      <a href={`/users/${userId}`}>View Profile</a>
    </div>
  );
}

const queryClient = new QueryClient();

async function prefetchOnRouteEnter(userId: number) {
  try {
    const user = await queryClient.fetchQuery({
      queryKey: ['user', userId],
      queryFn: () => fetchUser(userId),
      staleTime: 1000 * 60 * 5
    });
    console.log('Prefetched user:', user.name);
  } catch (error) {
    console.error('Prefetch failed:', error);
  }
}

'use client';

import { useQueryClient } from '@tanstack/react-query';
import { useCallback } from 'react';

function UserCard({ user }: { user: User }) {
  const queryClient = useQueryClient();

  const prefetchUser = useCallback(() => {
    queryClient.prefetchQuery({
      queryKey: ['user', user.id],
      queryFn: () => fetchUser(user.id),
      staleTime: 1000 * 60 * 5
    });
  }, [queryClient, user.id]);

  return (
    <a
      href={`/users/${user.id}`}
      onMouseEnter={prefetchUser}
    >
      {user.name}
    </a>
  );
}

const prefetchDashboard = async (queryClient: QueryClient) => {
  await Promise.all([
    queryClient.prefetchQuery({
      queryKey: ['stats'],
      queryFn: fetchStats
    }),
    queryClient.prefetchQuery({
      queryKey: ['recent-activity'],
      queryFn: fetchRecentActivity
    }),
    queryClient.prefetchQuery({
      queryKey: ['notifications'],
      queryFn: fetchNotifications
    })
  ]);
};

// Call this on route hover or page mount
prefetchDashboard(queryClient);
